/// @script: the #hb_script_t of the buffer, see hb_buffer_set_script().
/// @language: the #hb_language_t of the buffer, see hb_buffer_set_language().
///
/// The structure that holds various text properties of an #hb_buffer_t. Can be
/// set and retrieved using hb_buffer_set_segment_properties() and
/// hb_buffer_get_segment_properties(), respectively.
final class hb_segment_properties_t extends ffi.Struct {
  @ffi.UnsignedInt()
  external int directionAsInt;

  hb_direction_t get direction => hb_direction_t.fromValue(directionAsInt);
  set direction(hb_direction_t value) => directionAsInt = value.value;

  @ffi.UnsignedInt()
  external int scriptAsInt;

  hb_script_t get script => hb_script_t.fromValue(scriptAsInt);
  set script(hb_script_t value) => scriptAsInt = value.value;

  external hb_language_t language;

  /// < private >
  external ffi.Pointer<ffi.Void> reserved1;

  external ffi.Pointer<ffi.Void> reserved2;

  static ffi.Pointer<hb_segment_properties_t> $allocate(
    ffi.Allocator $allocator, {
    required hb_direction_t direction,
    required hb_script_t script,
    required hb_language_t language,
    required ffi.Pointer<ffi.Void> reserved1,
    required ffi.Pointer<ffi.Void> reserved2,
  }) => $allocator<hb_segment_properties_t>()
    ..ref.direction = direction
    ..ref.script = script
    ..ref.language = language
    ..ref.reserved1 = reserved1
    ..ref.reserved2 = reserved2;
}

